		const page1 = await context.newPage()
		await page1.goto(SITE + '/?note=' + encodeURIComponent(NOTE))
		await sleep(1000)
		await page1.close()

		const page2 = await context.newPage()
		console.log(`[+] Visiting ${url}`)
		page2.goto(url)
		await sleep(2000)
		await page2.close()

		await context.close()
		console.log('[+] Done')
		context = null
	} catch (e) {
		console.log(e)
	} finally {
		if (context) await context.close()
	}
}

module.exports = visit

